(5766958, 839628, 112818, '<td valign="top">Well seen &amp; well photographed</td>', 'Well seen & well photographed', '2009-12-14 13:33:17.000000', NULL, 1),
(5766959, 839695, 28427, '<td valign="top">Hmmm...this looks like <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=74588" rel="nofollow" target="_blank">cutout</a> style nut I might be wrong.  Intriguing image for sure.</td>', 'Hmmm...this looks like  cutout style nut I might be wrong.  Intriguing image for sure.', '2009-12-14 13:33:27.000000', NULL, 1),
(5766964, 839619, 28427, '<td valign="top">Great usage of HDR effect which gives an extra dimension to this work.</td>', 'Great usage of HDR effect which gives an extra dimension to this work.', '2009-12-14 13:35:27.000000', NULL, 1),
(5767046, 839536, 55956, '<td valign="top">nice perspective, good the choice for the black and white</td>', 'nice perspective, good the choice for the black and white', '2009-12-14 14:15:24.000000', NULL, 1),
