INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5768058, 839678, 109640, '<td valign="top">Great Picture!</td>', 'Great Picture!', '2009-12-15 16:37:42.000000', NULL, 1),
(5768062, 839628, 63398, '<td valign="top">This is my favorite image in this challenge. IMO, it''s the hands-down winner, regardless of its placement at the end. It shows creative vision on an incredible level, a lot of good fortune for it to be there in the first place, and you to find it, and skill and knowledge to shoot it and post-process it in such a manner. A veritable masterpiece in my eyes. Thank you for this magnificent piece of work!.....10</td>', 'This is my favorite image in this challenge. IMO, it''s the hands-down winner, regardless of its placement at the end. It shows creative vision on an incredible level, a lot of good fortune for it to be there in the first place, and you to find it, and skill and knowledge to shoot it and post-process it in such a manner. A veritable masterpiece in my eyes. Thank you for this magnificent piece of work!.....10', '2009-12-15 16:49:59.000000', NULL, 1),
(5768063, 838659, 63398, '<td valign="top">Fabulous find!.....9...some serious personification with that hole.</td>', 'Fabulous find!.....9...some serious personification with that hole.', '2009-12-15 16:50:24.000000', NULL, 1),
(5768064, 839544, 63398, '<td valign="top">I gave this an 8 based on the lighting, composition, and the fabulous perspective. Nicely done!</td>', 'I gave this an 8 based on the lighting, composition, and the fabulous perspective. Nicely done!', '2009-12-15 16:51:26.000000', NULL, 1),
(5768065, 839664, 63398, '<td valign="top">I love this. I don''t feel that technically it meets the challenge description of urban, but I think the image as a whole conveys the theme well enough that the urban thing is over-ridden by its terrific imagery......8</td>', 'I love this. I don''t feel that technically it meets the challenge description of urban, but I think the image as a whole conveys the theme well enough that the urban thing is over-ridden by its terrific imagery......8', '2009-12-15 16:53:31.000000', NULL, 1),
(5768066, 839497, 63398, '<td valign="top">This is almost too pretty to fit the description of decay.....and that''s what makes it such a terrific image IMO......8</td>', 'This is almost too pretty to fit the description of decay.....and that''s what makes it such a terrific image IMO......8', '2009-12-15 16:54:10.000000', NULL, 1),
(5768068, 839629, 63398, '<td valign="top">The fence and barbed wire really helps make this image stronger. Though I''d love to see the colors in this, the B&amp;W conversion helps with teh stark and bleak moodiness that this image conveys so very well.....8</td>', 'The fence and barbed wire really helps make this image stronger. Though I''d love to see the colors in this, the B&W conversion helps with teh stark and bleak moodiness that this image conveys so very well.....8', '2009-12-15 16:55:27.000000', NULL, 1),
(5768069, 839019, 57447, '<td valign="top">Good level shot of an elevated tower. Hope it''s out of service.</td>', 'Good level shot of an elevated tower. Hope it''s out of service.', '2009-12-15 16:56:31.000000', NULL, 1),
(5768238, 839237, 68256, '<td valign="top">I''m enjoying looking at this, it makes for an interesting b/w.  I think it needs some more contrast on the bricks to make the white "read" pop.  Great find though.</td>', 'I''m enjoying looking at this, it makes for an interesting b/w.  I think it needs some more contrast on the bricks to make the white "read" pop.  Great find though.', '2009-12-15 19:59:29.000000', NULL, 1),
(5768250, 838607, 68256, '<td valign="top">This is such an interseting composition.  I love the stark difference between the top level and bottom level.  I guess because the top is b/w and bottom in color, the top is symetrical and simple, bottom chaotic and ouit of balance.  Well anyway, I really like it.  Great eye.</td>', 'This is such an interseting composition.  I love the stark difference between the top level and bottom level.  I guess because the top is b/w and bottom in color, the top is symetrical and simple, bottom chaotic and ouit of balance.  Well anyway, I really like it.  Great eye.', '2009-12-15 20:06:22.000000', NULL, 1),
(5768258, 839630, 68256, '<td valign="top">Not a bad composition and I can see how it would appeal to hdr fans.  For my personal taste it is a little much.  I love the flow of the composition though and the color scheme.</td>', 'Not a bad composition and I can see how it would appeal to hdr fans.  For my personal taste it is a little much.  I love the flow of the composition though and the color scheme.', '2009-12-15 20:08:43.000000', NULL, 1),
(5768270, 839472, 68256, '<td valign="top">There is a softness to this that seems odd and the composition is not to my liking.  I do like the streaks of light and the chaotic wall murel.</td>', 'There is a softness to this that seems odd and the composition is not to my liking.  I do like the streaks of light and the chaotic wall murel.', '2009-12-15 20:13:16.000000', NULL, 1),
(5768287, 839451, 68256, '<td valign="top">I love the patterns of the pillars and wish I could see more of it.  I think it would have worked better without so much &lt;basically&gt; empty space on the left and more pillars.  Perhaps a portrait crop?</td>', 'I love the patterns of the pillars and wish I could see more of it.  I think it would have worked better without so much <basically> empty space on the left and more pillars.  Perhaps a portrait crop?', '2009-12-15 20:17:22.000000', NULL, 1),
(5768297, 839225, 68256, '<td valign="top">Great shot, I love the art on the bricks in the center.  The contrast of the letters really draws your eye in.  Great detail all around.  I also appreciate that you didn''t super duper HDR this.</td>', 'Great shot, I love the art on the bricks in the center.  The contrast of the letters really draws your eye in.  Great detail all around.  I also appreciate that you didn''t super duper HDR this.', '2009-12-15 20:22:52.000000', NULL, 1),
(5768307, 839637, 68256, '<td valign="top">Great composition, the interaction seems a little staged though for some reason.  I''m stuck in a box of decay and can''t see out of it to get your interpretation.  If their relationship is supposed to be decaying they don''t look mad at each other, she looks quite happy.  I gave it a try but just don''t get it.</td>', 'Great composition, the interaction seems a little staged though for some reason.  I''m stuck in a box of decay and can''t see out of it to get your interpretation.  If their relationship is supposed to be decaying they don''t look mad at each other, she looks quite happy.  I gave it a try but just don''t get it.', '2009-12-15 20:32:38.000000', NULL, 1),
(5768356, 839535, 63398, '<td valign="top">I like this as it''s a terrific find. I think I would have cropped it differently, but maybe not. Well done......8</td>', 'I like this as it''s a terrific find. I think I would have cropped it differently, but maybe not. Well done......8', '2009-12-15 21:25:16.000000', NULL, 1),
