INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5769761, 839628, 32011, '<td valign="top">This is my pick for the blue.  Colour, detail and composition all perfect.  Add to that the interesting and complex scene captured... standout image of the challenge.  Originally gave this an 8 but on further viewing during commenting, I''m bumping to a 9.</td>', 'This is my pick for the blue.  Colour, detail and composition all perfect.  Add to that the interesting and complex scene captured... standout image of the challenge.  Originally gave this an 8 but on further viewing during commenting, I''m bumping to a 9.', '2009-12-16 22:11:05.000000', NULL, 1),
(5769762, 839426, 32011, '<td valign="top">Amazing how you''ve managed to capture such ugly subject matter so beautifully.  Details and composition are wonderful, as are the colours. I really love the cloudscape, and that you''ve managed to capture "urban decay" without graffiti featuring as a significant item (seems rare in this challenge).  Great image overall, and I reckon this should finish in the top 10.</td>', 'Amazing how you''ve managed to capture such ugly subject matter so beautifully.  Details and composition are wonderful, as are the colours. I really love the cloudscape, and that you''ve managed to capture "urban decay" without graffiti featuring as a significant item (seems rare in this challenge).  Great image overall, and I reckon this should finish in the top 10.', '2009-12-16 22:15:53.000000', NULL, 1),
