(5773000, 839429, 76598, '<td valign="top">I suppose all the hot spots are the sun coming through holes in the roof, but they are really distracting</td>', 'I suppose all the hot spots are the sun coming through holes in the roof, but they are really distracting', '2009-12-20 06:31:05.000000', NULL, 1),
(5773002, 839479, 91691, '<td valign="top">a nice picture but i think would have been better if the dark foreground was croped out</td>', 'a nice picture but i think would have been better if the dark foreground was croped out', '2009-12-20 06:32:49.000000', NULL, 1),
(5773017, 839544, 86218, '<td valign="top">Wow. This is done superbly in my humble opinion. Lighting handled well and decay certainly prominent yet some hints of past beauty. 8</td>', 'Wow. This is done superbly in my humble opinion. Lighting handled well and decay certainly prominent yet some hints of past beauty. 8', '2009-12-20 07:50:14.000000', NULL, 1),
(5773020, 839497, 86218, '<td valign="top">Special place, special scene, well composed and together with decay really brought out the desolation with it. Like it very much. decaying beauty...is that possible, yet I find this in the pic 8</td>', 'Special place, special scene, well composed and together with decay really brought out the desolation with it. Like it very much. decaying beauty...is that possible, yet I find this in the pic 8', '2009-12-20 07:59:32.000000', NULL, 1),
(5773022, 839338, 86218, '<td valign="top">Simple pic made special with lighting and comp. Would like the bars in fore sharper as this to me forms an important part of pic that needs to be sharp for me in this scene. others might differ. Still a very well seen setting and well done on taking the shot</td>', 'Simple pic made special with lighting and comp. Would like the bars in fore sharper as this to me forms an important part of pic that needs to be sharp for me in this scene. others might differ. Still a very well seen setting and well done on taking the shot', '2009-12-20 08:03:29.000000', NULL, 1),
(5773091, 839541, 98339, '<td valign="top">I think that this used to be quite the posh area to live in during the early to mid 1900''s...what a shame...excellent job</td>', 'I think that this used to be quite the posh area to live in during the early to mid 1900''s...what a shame...excellent job', '2009-12-20 09:46:21.000000', NULL, 1),
(5773093, 839574, 98339, '<td valign="top">what an excellent picture...I like how the chair is singled out</td>', 'what an excellent picture...I like how the chair is singled out', '2009-12-20 09:46:40.000000', NULL, 1),
