(5773096, 839256, 98339, '<td valign="top">nice, open, breezy, could use a weed-eater although...great shot...</td>', 'nice, open, breezy, could use a weed-eater although...great shot...', '2009-12-20 09:47:56.000000', NULL, 1),
(5773097, 839277, 98339, '<td valign="top">I like how this looks like a painting...excellent job</td>', 'I like how this looks like a painting...excellent job', '2009-12-20 09:48:24.000000', NULL, 1),
(5773098, 838591, 98339, '<td valign="top">I really like the composition of this...well done</td>', 'I really like the composition of this...well done', '2009-12-20 09:48:59.000000', NULL, 1),
(5773212, 839689, 66635, '<td valign="top">This is very well composed.  I like the placement of the lighter-bricked corner right on the vertical third and then my eye goes to the people then to the one way arrow that shoots me over to the other side.  Good shot of urban decay, too.</td>', 'This is very well composed.  I like the placement of the lighter-bricked corner right on the vertical third and then my eye goes to the people then to the one way arrow that shoots me over to the other side.  Good shot of urban decay, too.', '2009-12-20 12:38:49.000000', NULL, 1),
(5773213, 839550, 66635, '<td valign="top">I like this very much.</td>', 'I like this very much.', '2009-12-20 12:39:55.000000', NULL, 1),
(5773282, 839692, 50641, '<td valign="top">nicely processed + good perspective</td>', 'nicely processed + good perspective', '2009-12-20 14:20:10.000000', NULL, 1),
(5773319, 839591, 100831, '<td valign="top">If it had been a sunny, beautiful day this wouldn''t have had the impact it does, imo. Great job. I''m afraid this sad story is becoming more real to too many people. 8</td>', 'If it had been a sunny, beautiful day this wouldn''t have had the impact it does, imo. Great job. I''m afraid this sad story is becoming more real to too many people. 8', '2009-12-20 15:56:27.000000', NULL, 1),
(5773381, 839628, 14867, '<td valign="top">One of the few in this (difficult) challenge hoisting above a documentary level and showing skill for creativity and composition.<br/>Your use of reflection (including the colors) is really great here.</td>', 'One of the few in this (difficult) challenge hoisting above a documentary level and showing skill for creativity and composition.Your use of reflection (including the colors) is really great here.', '2009-12-20 17:32:16.000000', NULL, 1),
(5773406, 838486, 102278, '<td valign="top">Great angle. Love the texture as well.</td>', 'Great angle. Love the texture as well.', '2009-12-20 18:03:36.000000', NULL, 1),
(5773415, 839005, 99506, '<td valign="top">fantastic choice for the challenge, great shot.</td>', 'fantastic choice for the challenge, great shot.', '2009-12-20 18:17:11.000000', NULL, 1),
(5773431, 839494, 108982, '<td valign="top">awesome use of color.  like the level of saturation very much especially in the sulfured yellows.  the center section is reminiscent of a waterfall of bricks.  very cool 9</td>', 'awesome use of color.  like the level of saturation very much especially in the sulfured yellows.  the center section is reminiscent of a waterfall of bricks.  very cool 9', '2009-12-20 18:40:43.000000', NULL, 1),
